package com.timemeasurer.app.core.player.sound

interface SoundPlayer {
    /**
     * Plays [soundId] once, or replaces any currently looping sound and vibration when [loop] is true.
     */
    fun play(soundId: String, vibrate: Boolean = false, loop: Boolean = false)

    /**
     * Stops looping sound, one-shot sounds and vibration.
     */
    fun stop()

    fun vibrate(durationMs: Long = 400L)
}
