package com.timemeasurer.app.core.common.di

import com.timemeasurer.app.core.common.AppLifecycleObserver
import com.timemeasurer.app.core.common.createAppLifecycleObserver
import com.timemeasurer.app.core.common.time.MonotonicClock
import com.timemeasurer.app.core.common.time.createMonotonicClock
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.CoroutineExceptionHandler
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import org.kodein.di.DI
import org.kodein.di.bind
import org.kodein.di.instance
import org.kodein.di.singleton

const val DI_MODULE_COMMON = "commonModule"
const val DI_TAG_DISPATCHER_IO = "coroutine_dispatcher_io"
const val DI_TAG_DISPATCHER_COMPUTE = "coroutine_dispatcher_compute"
const val DI_TAG_SCOPE_IO = "coroutine_scope_io"
const val DI_TAG_SCOPE_COMPUTE = "coroutine_scope_compute"

internal fun createSafeScope(
    dispatcher: CoroutineDispatcher,
    tag: String,
    onUncaught: (String, Throwable) -> Unit = { tag, t -> println("CoroutineScope($tag) - uncaught: $t") },
): CoroutineScope =
    CoroutineScope(
        SupervisorJob() + dispatcher + CoroutineExceptionHandler { _, throwable ->
            onUncaught(tag, throwable)
        }
    )

val commonModule = DI.Module(DI_MODULE_COMMON) {
    bind<CoroutineDispatcher>(tag = DI_TAG_DISPATCHER_IO) with singleton {
        Dispatchers.Default.limitedParallelism(parallelism = 64, name = DI_TAG_DISPATCHER_IO)
    }
    bind<CoroutineDispatcher>(tag = DI_TAG_DISPATCHER_COMPUTE) with singleton {
        Dispatchers.Default
    }
    bind<CoroutineScope>(tag = DI_TAG_SCOPE_IO) with singleton {
        createSafeScope(instance<CoroutineDispatcher>(tag = DI_TAG_DISPATCHER_IO), DI_TAG_SCOPE_IO)
    }
    bind<CoroutineScope>(tag = DI_TAG_SCOPE_COMPUTE) with singleton {
        createSafeScope(instance<CoroutineDispatcher>(tag = DI_TAG_DISPATCHER_COMPUTE), DI_TAG_SCOPE_COMPUTE)
    }
    bind<MonotonicClock>() with singleton { createMonotonicClock() }
    bind<AppLifecycleObserver>() with singleton { createAppLifecycleObserver() }
}