package com.timemeasurer.app.core.navigation

object CustomListDetailKeys {
    const val PaneRoleKey = "timemeasurer.statistics.pane_role"
    const val ListRole = "list"
    const val DetailRole = "detail"

    fun listPane(): Map<String, Any> = mapOf(PaneRoleKey to ListRole)
    fun detailPane(): Map<String, Any> = mapOf(PaneRoleKey to DetailRole)
}
