package com.timemeasurer.app

import androidx.compose.runtime.Composable
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.close
import com.timemeasurer.app.core.resources.privacy_policy_message
import com.timemeasurer.app.core.resources.privacy_policy_read
import com.timemeasurer.app.core.resources.privacy_policy_title
import com.timemeasurer.app.core.resources.privacy_policy_url
import com.timemeasurer.app.core.ui.system.rememberUrlOpener
import com.timemeasurer.app.core.ui.widgets.PrivacyPolicyDialog
import org.jetbrains.compose.resources.stringResource

@Composable
fun PrivacyPolicyDialogHost(onDismiss: () -> Unit) {
    val openUrl = rememberUrlOpener()
    val privacyPolicyUrl = stringResource(Res.string.privacy_policy_url)

    PrivacyPolicyDialog(
        title = stringResource(Res.string.privacy_policy_title),
        message = stringResource(Res.string.privacy_policy_message),
        readLabel = stringResource(Res.string.privacy_policy_read),
        closeLabel = stringResource(Res.string.close),
        onRead = {
            openUrl(privacyPolicyUrl)
            onDismiss()
        },
        onClose = onDismiss,
    )
}
