package com.timemeasurer.app.core.domain.sound

import com.timemeasurer.app.core.model.timer.TimerSettingsModel
import com.timemeasurer.app.core.model.timer.TimerTypeModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow

class TimerSoundInteractor(
    private val playTimerCountdownSoundUseCase: PlayTimerCountdownSoundUseCase,
    private val playTimerPeriodEndSoundUseCase: PlayTimerPeriodEndSoundUseCase,
    private val playSoundPreviewUseCase: PlaySoundPreviewUseCase,
    private val stopSoundUseCase: StopSoundUseCase,
) {
    private val _periodEndOwnerId = MutableStateFlow<Long?>(null)
    val periodEndOwnerId: StateFlow<Long?> = _periodEndOwnerId

    fun playCountdown(settings: TimerSettingsModel) {
        playTimerCountdownSoundUseCase(settings)
    }

    suspend fun playPeriodEnd(timerId: Long, settings: TimerSettingsModel, type: TimerTypeModel): Boolean {
        val played = playTimerPeriodEndSoundUseCase(
            settings,
            type,
            stopCurrent = _periodEndOwnerId.value != null,
        )
        if (played) _periodEndOwnerId.value = timerId.takeIf { settings.isEndSoundLooped }
        return played
    }

    fun stop() {
        stopSoundUseCase()
        _periodEndOwnerId.value = null
    }

    fun stopPeriodEndSound(timerId: Long? = null) {
        val owner = _periodEndOwnerId.value ?: return
        if (timerId != null && owner != timerId) return
        stop()
    }

    fun playPreview(soundId: String) {
        playSoundPreviewUseCase(soundId)
    }
}
