@Composable
fun TimerMuteButton(
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
) {
    FloatingActionButton(
        onClick = onClick,
        elevation = FloatingActionButtonDefaults.elevation(defaultElevation = 0.dp),
        modifier = modifier,
    ) {
        Icon(
            imageVector = CommonIconSet.volumeOff.icon,
            contentDescription = stringResource(Res.string.timer_mute_sound),
        )
    }
}

