package com.timemeasurer.app.feature.stopwatches.widgets

import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.material3.LocalContentColor
import androidx.compose.material3.MaterialTheme
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.tooling.preview.Preview
import com.timemeasurer.app.core.ui.theme.timeDisplayFontFamily
import com.timemeasurer.app.core.ui.widgets.AutoSizeText

@Composable
fun StopwatchDisplay(
    time: String,
    modifier: Modifier = Modifier
) {
    AutoSizeText(
        text = time,
        style = MaterialTheme.typography.displayLarge.copy(
            fontFamily = timeDisplayFontFamily(),
        ),
        color = LocalContentColor.current.copy(alpha = 0.7f),
        textAlign = TextAlign.Center,
        modifier = modifier.fillMaxWidth()
    )
}

@Preview
@Composable
private fun StopwatchDisplayPreview() {
    StopwatchDisplay(time = "01:23.45")
}

